import java.io.*;
import java.util.*;

public class Main {
    // Fenwick Tree / Binary Indexed Tree
    static class Fenwick {
        int n;
        int[] bit;

        Fenwick(int n) {
            this.n = n;
            this.bit = new int[n + 2];
        }

        void add(int idx, int val) {
            while (idx <= n) {
                bit[idx] += val;
                idx += idx & -idx;
            }
        }

        int sum(int idx) {
            int res = 0;
            while (idx > 0) {
                res += bit[idx];
                idx -= idx & -idx;
            }
            return res;
        }

        int rangeSum(int l, int r) {
            return sum(r) - sum(l - 1);
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        String S = fs.next();
        int Q = fs.nextInt();

        char[] arr = (" " + S).toCharArray(); // 1-indexed

        Fenwick[] trees = new Fenwick[26];
        for (int i = 0; i < 26; i++) trees[i] = new Fenwick(N);

        for (int i = 1; i <= N; i++) {
            trees[arr[i] - 'a'].add(i, 1);
        }

        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < Q; qi++) {
            int type = fs.nextInt();
            if (type == 1) {
                int idx = fs.nextInt();
                char c = fs.next().charAt(0);
                if (arr[idx] != c) {
                    trees[arr[idx] - 'a'].add(idx, -1);
                    trees[c - 'a'].add(idx, 1);
                    arr[idx] = c;
                }
            } else {
                int l = fs.nextInt();
                int r = fs.nextInt();
                int ans = 0;
                for (int ch = 0; ch < 26; ch++) {
                    if (trees[ch].rangeSum(l, r) > 0) ans++;
                }
                out.append(ans).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

import sys

input = sys.stdin.readline

class SegmentTree:
    def __init__(self, s):
        self.n = len(s)
        self.size = 1
        while self.size < self.n:
            self.size <<= 1
        self.data = [0] * (2 * self.size)
        for i, ch in enumerate(s):
            self.data[self.size + i] = 1 << (ord(ch) - 97)
        for i in range(self.size - 1, 0, -1):
            self.data[i] = self.data[2*i] | self.data[2*i+1]

    def update(self, idx, ch):
        bit = 1 << (ord(ch) - 97)
        pos = idx + self.size
        if self.data[pos] == bit:
            return
        self.data[pos] = bit
        pos >>= 1
        while pos:
            self.data[pos] = self.data[2*pos] | self.data[2*pos+1]
            pos >>= 1

    def query(self, l, r):
        l += self.size
        r += self.size
        res = 0
        while l <= r:
            if l & 1:
                res |= self.data[l]
                l += 1
            if not (r & 1):
                res |= self.data[r]
                r -= 1
            l >>= 1
            r >>= 1
        return bin(res).count("1")

def main():
    n = int(input())
    s = input().strip()
    q = int(input())
    seg = SegmentTree(s)
    out_lines = []
    for _ in range(q):
        parts = input().split()
        if parts[0] == '1':
            i = int(parts[1]) - 1
            c = parts[2]
            seg.update(i, c)
        else:
            l = int(parts[1]) - 1
            r = int(parts[2]) - 1
            out_lines.append(str(seg.query(l, r)))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
