import sys

class BIT:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        return self.sum(r) - self.sum(l - 1)


def main():
    input = sys.stdin.readline

    N = int(input())
    S = list(input().strip())
    Q = int(input())

    # One BIT per character
    bits = [BIT(N) for _ in range(26)]

    for i, ch in enumerate(S, 1):
        bits[ord(ch) - 97].add(i, 1)

    out = []

    for _ in range(Q):
        q = input().split()
        if q[0] == '1':
            i = int(q[1])
            c = q[2]
            old = S[i - 1]
            if old != c:
                bits[ord(old) - 97].add(i, -1)
                bits[ord(c) - 97].add(i, 1)
                S[i - 1] = c
        else:
            l = int(q[1])
            r = int(q[2])
            ans = 0
            for k in range(26):
                if bits[k].range_sum(l, r) > 0:
                    ans += 1
            out.append(str(ans))

    print('\n'.join(out))


